import React, { useContext, useMemo } from 'react';
import { PageContext } from '../frontend/pageContext';
import { staticAssetUrl } from '../frontend/utils';
import { ClientMenuLink } from '../types';
import { menuPathsMatch } from './utils';

interface Props {
  menu: any;
}

interface DocNavLink {
  url: string;
  title: string;
}

/**
 * Resolves whether a menu path is the current page.
 * Live paths match exactly; static relative paths use menuPathsMatch.
 */
const isCurrentPage = (
  itemPath: string | undefined,
  searchPath: string,
  isStatic?: boolean,
) => {
  if (!itemPath) {
    return false;
  }
  if (itemPath === searchPath) {
    return true;
  }
  return Boolean(isStatic && menuPathsMatch(itemPath, searchPath));
};

const getItemInfo = (item: any): DocNavLink | undefined => {
  if (item?.type === 'externalMenuLink') {
    return {
      url: (item as ClientMenuLink).url,
      title: (item as ClientMenuLink).text,
    };
  }

  if (item?.type === 'menuLink') {
    return {
      url: item.path,
      title: item.text,
    };
  }

  return undefined;
};

/**
 * Flattens menu links in walk order for prev/next resolution.
 */
const flattenMenuLinks = (items: any[], acc: DocNavLink[] = []): DocNavLink[] => {
  for (const item of items) {
    const currentItem = getItemInfo(item);
    if (
      (item.type === 'menuLink' || item.type === 'externalMenuLink') &&
      currentItem
    ) {
      acc.push(currentItem);
    }
    if (item.children?.length) {
      flattenMenuLinks(item.children, acc);
    }
  }
  return acc;
};

const PageNavButtons = ({ menu }: Props) => {
  const { pathname, isStatic, relPath } = useContext(PageContext);
  const asset = (assetPath: string) =>
    staticAssetUrl(isStatic, relPath, assetPath);

  // Compute during render so static SSR (and hydrate) get prev/next.
  // useEffect does not run during generateStatic renderToString.
  const { prevLink, nextLink } = useMemo(() => {
    const searchPath = pathname.split('#')[0];
    const flat = flattenMenuLinks(menu?.children ?? []);
    const currentIndex = flat.findIndex((link) =>
      isCurrentPage(link.url, searchPath, isStatic),
    );
    return {
      prevLink:
        currentIndex > 0 ? flat[currentIndex - 1].url : undefined,
      nextLink:
        currentIndex >= 0 && currentIndex < flat.length - 1
          ? flat[currentIndex + 1].url
          : undefined,
    };
  }, [menu, pathname, isStatic]);

  const isExternalLink = (url: string) => {
    return url.startsWith('http://') || url.startsWith('https://');
  };

  return (
    <>
      {prevLink && (
        <a
          href={prevLink}
          className="prev-btn"
          {...(isExternalLink(prevLink) && {
            target: '_blank',
            rel: 'noopener noreferrer',
          })}
        >
          {!isExternalLink(prevLink) && (
            <svg>
              <use
                href={asset('/assets/images/left-arrow.svg#left-arrow')}
                fill="currentColor"
              ></use>
            </svg>
          )}
          <div className="nav-btn-text">
            <span>Prev</span>
            {isExternalLink(prevLink) && (
              <svg className="external-link-icon">
                <use
                  href={asset('/assets/images/offsite.svg#offsite')}
                  fill="currentColor"
                ></use>
              </svg>
            )}
          </div>
        </a>
      )}
      {nextLink && (
        <a
          href={nextLink}
          className="next-btn"
          {...(isExternalLink(nextLink) && {
            target: '_blank',
            rel: 'noopener noreferrer',
          })}
        >
          <div className="nav-btn-text">
            <span>Next</span>
            {isExternalLink(nextLink) && (
              <svg className="external-link-icon">
                <use
                  href={asset('/assets/images/offsite.svg#offsite')}
                  fill="currentColor"
                ></use>
              </svg>
            )}
          </div>
          {!isExternalLink(nextLink) && (
            <svg>
              <use
                href={asset('/assets/images/right-arrow.svg#right-arrow')}
                fill="currentColor"
              ></use>
            </svg>
          )}
        </a>
      )}
    </>
  );
};

export default PageNavButtons;
